// KlonSim ODE model — Daisy Seed / Hothouse firmware
//
// Signal chain (matches Python WH model exactly):
//   in → HPF1(80 Hz) → ×drive → tanhf → HPF2(350 Hz) → Shelf(3 kHz, +2 dB) → ×level → out
//
// Controls:
//   FOOTSWITCH_1 (left)       : press to toggle effect on/off
//   FOOTSWITCH_1+2 both held  : reset to DFU bootloader after 2 s (for reflashing)
//   LED_1 (left)              : on when effect is engaged, off when bypassed
//   TOGGLESWITCH_3 UP         : LED_2 (right) blinks at 1 Hz as heartbeat
//   TOGGLESWITCH_3 other pos  : LED_2 off
//
// Coefficients are generated by:
//   uv run python scripts/export_daisy_coeffs.py
//
// Build and flash (from results/pedalode/klonsim_v1/daisy/):
//   make && make program-dfu

#include "hothouse.h"
#include "klonsim_params.h"

#include <cmath>

using clevelandmusicco::Hothouse;
using daisy::AudioHandle;
using daisy::Led;
using daisy::SaiHandle;
using daisy::System;

static Hothouse hw;
static Led      led_bypass;    // left LED  — on when effect is active
static Led      led_heartbeat; // right LED — 1 Hz blink when TOGGLESWITCH_3 is UP
static bool     bypassed = true;

// Direct Form II Transposed biquad.
struct Biquad {
    const float* b;  // feedforward [b0, b1, b2]
    const float* a;  // feedback    [a1, a2]
    float w[2] = {0.0f, 0.0f};

    float Process(float x) noexcept {
        const float y = b[0] * x + w[0];
        w[0] = b[1] * x - a[0] * y + w[1];
        w[1] = b[2] * x - a[1] * y;
        return y;
    }

    void Reset() noexcept { w[0] = w[1] = 0.0f; }
};

static Biquad hpf1  = { klonsim::kHpf1B,  klonsim::kHpf1A  };
static Biquad hpf2  = { klonsim::kHpf2B,  klonsim::kHpf2A  };
static Biquad shelf = { klonsim::kShelfB, klonsim::kShelfA };

static void AudioCallback(AudioHandle::InputBuffer  in,
                          AudioHandle::OutputBuffer out,
                          size_t                    size)
{
    hw.ProcessAllControls();

    if (hw.switches[Hothouse::FOOTSWITCH_1].RisingEdge()) {
        bypassed = !bypassed;
        if (!bypassed) {
            hpf1.Reset();
            hpf2.Reset();
            shelf.Reset();
        }
        led_bypass.Set(bypassed ? 0.0f : 1.0f);
    }
    led_bypass.Update();

    for (size_t i = 0; i < size; ++i) {
        float x = in[0][i];

        if (!bypassed) {
            x = hpf1.Process(x);
            x = tanhf(x * klonsim::kDrive);
            x = hpf2.Process(x);
            x = shelf.Process(x);
            x *= klonsim::kOutputLevel;
        }

        out[0][i] = out[1][i] = x;
    }
}

int main()
{
    hw.Init();
    hw.SetAudioBlockSize(4);
    hw.SetAudioSampleRate(SaiHandle::Config::SampleRate::SAI_48KHZ);

    led_bypass.Init(hw.seed.GetPin(Hothouse::LED_1), false);
    led_bypass.Set(0.0f);
    led_bypass.Update();

    led_heartbeat.Init(hw.seed.GetPin(Hothouse::LED_2), false);
    led_heartbeat.Set(0.0f);
    led_heartbeat.Update();

    hw.StartAdc();
    hw.StartAudio(AudioCallback);

    uint32_t last_blink_ms = 0;
    bool     blink_state   = false;

    while (true) {
        hw.DelayMs(10);
        hw.CheckResetToBootloader();

        // Heartbeat: 1 Hz blink on right LED when TOGGLESWITCH_3 is UP
        uint32_t now = System::GetNow();
        if (hw.GetToggleswitchPosition(Hothouse::TOGGLESWITCH_3) == Hothouse::TOGGLESWITCH_UP) {
            if (now - last_blink_ms >= 500) {
                blink_state   = !blink_state;
                last_blink_ms = now;
            }
            led_heartbeat.Set(blink_state ? 1.0f : 0.0f);
        } else {
            blink_state   = false;
            last_blink_ms = now;
            led_heartbeat.Set(0.0f);
        }
        led_heartbeat.Update();
    }
}
